const autoResolveBibliography = `-- name: AutoResolveBibliography :exec
WITH resolution AS (
    SELECT id
    FROM publication_resolution r
    WHERE r.import_id = $1
        AND r.status = 'pending'
),
ranked_candidates AS (
    SELECT pc.id,
        pc.resolution_id,
        pc.match_type,
        pc.score,
        ROW_NUMBER() OVER (
            PARTITION BY pc.resolution_id
            ORDER BY pc.score DESC,
                pc.id
        ) AS rn,
        LEAD(pc.score) OVER (
            PARTITION BY pc.resolution_id
            ORDER BY pc.score DESC,
                pc.id
        ) AS next_score
    FROM publication_candidates pc
        JOIN resolution r ON pc.resolution_id = r.id
),
resolved_candidates AS (
    SELECT id,
        resolution_id
    FROM ranked_candidates
    WHERE rn = 1
        AND (
            match_type = 'doi'::pub_match_type
            OR (
                score >= $2
                AND COALESCE(score - next_score, score) >= $3
            )
        )
)
UPDATE publication_resolution r
SET status = 'auto_resolved',
    resolved_candidate_id = rc.id
FROM resolved_candidates rc
WHERE r.id = rc.resolution_id
`

